WITH base AS (SELECT *, TRIM(device_code) AS clean_device_code FROM device_readings WHERE reading_ts > DATE '2025-09-01') SELECT CASE WHEN pressure >= 1024 THEN 'PREMIUM' ELSE 'STANDARD' END AS pressure_tier, SORT_ARRAY(COLLECT_SET(device_code)) AS device_code_list, MAX(status_bits) FILTER (WHERE device_code = 'DV-01') AS dv_01_max_status_bits, AVG(pressure) FILTER (WHERE device_code = 'DV-01') AS dv_01_avg_pressure, PERCENTILE_APPROX(temp_c, ARRAY(0.25, 0.5, 0.75)) AS temp_c_quartiles, SUM(status_bits) FILTER (WHERE device_code = 'DV-02') AS dv_02_total_status_bits, MIN(humidity) AS min_humidity FROM base GROUP BY CASE WHEN pressure >= 1024 THEN 'PREMIUM' ELSE 'STANDARD' END HAVING dv_02_total_status_bits < 1000000 ORDER BY dv_01_avg_pressure NULLS LAST;
